{"width":80,"height":22,"fontSize":16,"fontWeight":500,"fontColor":"#ffffffff","maxLines":1}},{"id":"main_divider","component":"Divider","styles":{"width":1,"height":76,"vertical":true,"strokeWidth":1,"color":"#33ffffff"}},{"id":"support_column","component":"Column","children":["support_top_row","forecast_text","action_button"],"itemMargin":8,"styles":{"width":113,"height":84,"justifyContent":"start","alignItems":"end"}},{"id":"support_top_row","component":"Row","children":["air_text","humidity_text"],"itemMargin":6,"styles":{"width":113,"height":18,"justifyContent":"start","alignItems":"center"}},{"id":"air_text","component":"Text","content":"{{ '空气 ' + ${/data/weather/current/airQuality} }}","styles":{"width":52,"height":18,"fontSize":12,"fontWeight":500,"fontColor":"#ffffffff","maxLines":1}},{"id":"humidity_text","component":"Text","content":"{{ '湿度 ' + ${/data/weather/current/humidityPercent} + '%' }}","styles":{"width":55,"height":18,"fontSize":12,"fontWeight":500,"fontColor":"#ffffffff","maxLines":1}},{"id":"forecast_text","component":"Text","content":"{{ '今日 ' + ${/data/weather/daily/0/temperatureRangeText} + ' 降雨' + ${/data/weather/daily/0/rainProbabilityPercent} }}","styles":{"width":113,"height":18,"fontSize":12,"fontWeight":500,"fontColor":"#99ffffff","maxLines":1,"textAlign":"end"}},{"id":"action_button","component":"Button","label":"看天气","onClick":[{"call":"clickToDeeplink","args":{"bundleName":"","abilityName":"","uri":"hww://www.huawei.com/totemweather?enterType=share&cityCode="}}],"styles":{"width":88,"height":32,"borderRadius":16,"backgroundColor":"#ffffffff","fontSize":14,"fontWeight":500,"fontColor":"#ff0a59f7"}}]}}
